from ta_ue_plugin_qualcomm.ue.qualcomm.qc_ue_exceptions import DataTransferCreationException


def prepare_command_tails(ue_type, target_ip, source_ip, dt_definition):
    """
    :param ue_type:             ue_type
    :param source_ip:           argument od iperf -B command
    :param target_ip:           argument of iperf -c command
    :param dt_definition:       data transfer definition
    :return:                    tuple of iperf commands (sender, receiver)
    """
    if dt_definition.protocol.upper() in ["ICMP"]:
        sender_tail, receiver_tail = prepare_ping_tail(ue_type, target_ip, dt_definition)
    elif dt_definition.protocol.upper() in ["UDP", "TCP"]:
        sender_tail, receiver_tail = prepare_iperf_tail(target_ip, source_ip, dt_definition)
    else:
        raise DataTransferCreationException("%s protocol command generation is not supported" % dt_definition.protocol)
    return sender_tail, receiver_tail


def prepare_iperf_tail(target_ip, source_ip, dt_definition):
    """
    :param source_ip:           argument of iperf -B command
    :param target_ip:           argument of iperf -c command
    :param dt_definition:       data transfer definition
    :param kwargs:              iperf_params:  bandwidth, time, length, parraler, window, window_client, set-mss, omit
    :return:                    tuple of iperf commands (sender, receiver)
    """
    iperf_receiver_params = {
        '--interval': dt_definition.protocol_details.get('interval', 1),
        '--port': dt_definition.protocol_details.get('port'),
        '--len': dt_definition.protocol_details.get('len'),
        '--window': dt_definition.protocol_details.get('window'),
        '--mss': dt_definition.protocol_details.get('mss'),
        # '--bind': target_ip,
    }

    iperf_sender_params = {
        '--interval': dt_definition.protocol_details.get('interval', 1),
        '--port': dt_definition.protocol_details.get('port'),
        '--time': dt_definition.duration,
        '--length': dt_definition.protocol_details.get('length'),
        '--len': dt_definition.protocol_details.get('len'),
        '--window': dt_definition.protocol_details.get('window_client'),
        '--parallel': dt_definition.protocol_details.get('parallel'),
        '--mss': dt_definition.protocol_details.get('mss'),
        '--set-mss': dt_definition.protocol_details.get('set-mss'),
        '--omit': dt_definition.protocol_details.get('omit'),
        '--bandwidth': dt_definition.protocol_details.get('bandwidth'),
        # '--bind': source_ip,
    }

    receiver_cmd_tail = "--server "
    sender_cmd_tail = "--client {} ".format(target_ip)

    receiver_cmd_tail, sender_cmd_tail = _apply_protocol(dt_definition, receiver_cmd_tail, sender_cmd_tail)

    for (appender, value) in iperf_receiver_params.items():
        if value is not None:
            receiver_cmd_tail += "{} {} ".format(appender, value)
    for (appender, value) in iperf_sender_params.items():
        if value is not None:
            sender_cmd_tail += "{} {} ".format(appender, value)

    # from robot.api import logger
    # logger.info("Prepared tail for sender iperf command: {}".format(sender_cmd_tail))
    # logger.info("Prepared tail for receiver iperf command: {}".format(receiver_cmd_tail))

    return sender_cmd_tail, receiver_cmd_tail

# ping [-LRUbdfnqrvVaAB] [-c count] [-m mark] [-i interval] [-l preload]
#      [-p pattern] [-s packetsize] [-t ttl] [-w deadline] [-F flowlabel]
#      [-I interface] [-M hint] [-N nioption] [-Q tos] [-S sndbuf]
#      [-T timestamp option] [-W timeout] [hop ...] destination


