# allowed_packet_loss = self._get_ping_parameter('allowed_packet_loss')


def prepare_ping_tail(ue_type, target_ip, dt_definition):
    """
    :param ue_type:             ue_type
    :param target_ip:           argument of ping
    :param dt_definition:       data transfer definition
    :return:                    tuple of ping commands (sender, receiver)
    """
    target_ip = dt_definition.protocol_details.get('ping_host_ip', target_ip)

    """Usage: ping [-t] [-a] [-n count] [-l size] [-f] [-i TTL] [-v TOS]
        [-r count] [-s count] [[-j host-list] | [-k host-list]]
        [-w timeout] [-R] [-S srcaddr] [-4] [-6] target_name

    Options:
        -t             Ping the specified host until stopped.
                       To see statistics and continue - type Control-Break;
                       To stop - type Control-C.
        -a             Resolve addresses to hostnames.
        -n count       Number of echo requests to send.
        -l size        Send buffer size.
        -f             Set Don't Fragment flag in packet (IPv4-only).
        -i TTL         Time To Live.
        -v TOS         Type Of Service (IPv4-only. This setting has been deprecated
                       and has no effect on the type of service field in the IP Header).
        -r count       Record route for count hops (IPv4-only).
        -s count       Timestamp for count hops (IPv4-only).
        -j host-list   Loose source route along host-list (IPv4-only).
        -k host-list   Strict source route along host-list (IPv4-only).
        -w timeout     Timeout in milliseconds to wait for each reply.
        -R             Use routing header to test reverse route also (IPv6-only).
        -S srcaddr     Source address to use.
        -4             Force using IPv4.
        -6             Force using IPv6.
    """

    ping_params_windows = {
        '-n': _get_ping_count(dt_definition, cmd_type='windows'),  # for windows interval is always 1s=> count==duration
        '-l': dt_definition.protocol_details.get('size'),
        '-i': dt_definition.protocol_details.get('ttl'),
        '-v': dt_definition.protocol_details.get('tos'),
        '-r': dt_definition.protocol_details.get('record_route'),
        '-w': dt_definition.protocol_details.get('timeout'),
        '-S': dt_definition.protocol_details.get('srcaddr'),
    }

    """
    Usage: ping [-aAbBdDfhLnOqrRUvV] [-c count] [-i interval] [-I interface]
        [-m mark] [-M pmtudisc_option] [-l preload] [-p pattern] [-Q tos]
        [-s packetsize] [-S sndbuf] [-t ttl] [-T timestamp_option]
        [-w deadline] [-W timeout] [hop1 ...] destination
    """

    ping_params_linux = {
        '-c': _get_ping_count(dt_definition, cmd_type='linux'),
        '-m': dt_definition.protocol_details.get('mark'),
        '-i': dt_definition.protocol_details.get('interval'),
        '-l': dt_definition.protocol_details.get('preload'),
        '-p': dt_definition.protocol_details.get('pattern'),
        '-s': dt_definition.protocol_details.get('packetsize'),
        '-t': dt_definition.protocol_details.get('ttl'),
        '-w': dt_definition.protocol_details.get('deadline'),
        '-F': dt_definition.protocol_details.get('flowlabel'),
        '-I': dt_definition.protocol_details.get('interface'),
        '-M': dt_definition.protocol_details.get('pmtudisc_option'),
        '-Q': dt_definition.protocol_details.get('tos'),
        '-S': dt_definition.protocol_details.get('sndbuf'),
        '-T': dt_definition.protocol_details.get('timestamp'),
        '-W': dt_definition.protocol_details.get('timeout'),
    }

    if _is_linux_ping_cmd(ue_type, dt_definition):
        ping_params = ping_params_linux
    else:
        ping_params = ping_params_windows

    ping_cmd_tail = ''
    for (appender, value) in ping_params.items():
        if value is not None:
            ping_cmd_tail += "{} {} ".format(appender, value)

    # if not given explicitly, take app svr ip or ue_ip depends on direction

    ping_cmd_tail += "{} ".format(target_ip)
    return ping_cmd_tail, ping_cmd_tail


def _get_ping_count(dt_definition, cmd_type='linux'):
    count = dt_definition.protocol_details.get('count')
    ping_count = dt_definition.protocol_details.get('ping_count', count)  # for compatibility with android ue impl
    if dt_definition.is_forever_duration() and ping_count is not None:
        return int(ping_count)
    elif ping_count is not None:
        raise DataTransferCreationException("Could not apply duration and count/ping_count parameters in the same time."
                                            " Please choose only one")
    else:
        interval = 1.0 if cmd_type == 'windows' else dt_definition.protocol_details.get('interval', 1.0)
        calculated_count = int(dt_definition.duration / float(interval))
        return calculated_count


def _is_linux_ping_cmd(ue_type, dt_definition):
    return False if (dt_definition.direction.upper() == 'UL' and ue_type == 'LINUX') else True


def _apply_protocol(dt_definition, receiver_cmd_tail, sender_cmd_tail):
    if dt_definition.protocol.upper() == "UDP":
        sender_cmd_tail += "--udp "
        receiver_cmd_tail += "--udp "
    return receiver_cmd_tail, sender_cmd_tail
